// Point Cloud parity: the web's batched points must land exactly where the
// desktop's do, in the same order, in the same colours.
//
// The reference JSON is generated by tools/dump_point_cloud.py running the REAL
// desktop `glyphviz_core.point_cloud` — `cloud_parent_ids`, `point_size`,
// `drawable_children` and `build_batch`, the last fed from a live `Scene`'s
// baked transforms exactly as `Viewport._draw_point_clouds` feeds it.
// Regenerate it whenever the fixture CSV or either side's placement math
// changes.
//
// The positions are the check worth having. A cloud's points get no Object3D on
// this side, so the overlay has to place them from data — and this says that
// doing so agrees with `compute_world_transforms` through a rotated,
// non-uniformly scaled ancestor chain, through `topo_scale`, and through a World
// Grid parent's geography. `ids` is diffed in order for a separate reason: index
// i in the vertex array and index i in `ids` are the same node, and that is the
// whole of what makes a point pickable.

import { describe, expect, it } from 'vitest'
import * as THREE from 'three'
import { buildScene } from './buildScene'
import { pointSize } from '../gv/pointCloud'
import { parseGvNodeCsv } from '../gv/nodeCsv'
import type { GvNode } from '../gv/types'
import pointCloudCsv from '../gv/fixtures/point_cloud_gv_node.csv?raw'
import referenceRaw from '../gv/fixtures/point_cloud_batches.json?raw'

interface CloudEntry {
  parent_id: number
  point_size: number
  parent_hidden: boolean
  ids: number[]
  positions: [number, number, number][]
  colors: [number, number, number, number][]
}

interface Reference {
  source: string
  base_scale: number
  cloud_parent_ids: number[]
  point_size_by_ratio: [number, number][]
  clouds: CloudEntry[]
  clouds_show_hidden: CloudEntry[]
}

const reference = JSON.parse(referenceRaw) as Reference

/** Positions are float32 on this side and float64 on the desktop's. */
const TOLERANCE = 1e-5

function parse(): GvNode[] {
  const parsed = parseGvNodeCsv(pointCloudCsv)
  expect(parsed.errors).toEqual([])
  return parsed.nodes
}

/** The batches the overlay actually drew, keyed by cloud parent id. */
function batchesOf(nodes: GvNode[], showHidden: boolean) {
  const built = buildScene(nodes, { showHidden })
  // World matrices the overlay reads must be the ones this graph composes.
  built.root.updateMatrixWorld(true)
  built.clouds.update()
  const out = new Map<number, { ids: number[]; positions: Float32Array; colors: Float32Array }>()
  for (const batch of built.clouds.batches()) {
    // Every batch belongs to exactly one parent; find it through any of its
    // points, since a batch does not carry the parent id itself.
    const parentId = nodes.find((n) => n.id === batch.ids[0])!.parentId
    out.set(parentId, {
      ids: [...batch.ids],
      positions: batch.positions,
      colors: batch.colors,
    })
  }
  return { built, out }
}

describe('point cloud parity with the desktop engine', () => {
  it('finds the same cloud parents', () => {
    const nodes = parse()
    const built = buildScene(nodes)
    expect([...built.clouds.parentIds].sort((a, b) => a - b)).toEqual(
      // The desktop lists every cloud parent in the file; the overlay only holds
      // the ones that DREW, so an empty cloud and a hidden one are absent here.
      reference.cloud_parent_ids.filter((id) => {
        const entry = reference.clouds.find((c) => c.parent_id === id)!
        return !entry.parent_hidden && entry.ids.length > 0
      }),
    )
  })

  it('converts ratio to point size exactly, clamps included', () => {
    const node = parse()[0]
    for (const [ratio, expected] of reference.point_size_by_ratio) {
      expect(pointSize({ ...node, ratio })).toBe(expected)
    }
  })

  for (const [label, key] of [
    ['default', 'clouds'],
    ['with Show Hidden Nodes', 'clouds_show_hidden'],
  ] as const) {
    describe(label, () => {
      const showHidden = key === 'clouds_show_hidden'

      it('draws the same points, in the same order', () => {
        const { out } = batchesOf(parse(), showHidden)
        for (const entry of reference[key]) {
          const drawn = out.get(entry.parent_id)
          if (entry.parent_hidden || entry.ids.length === 0) {
            expect(drawn, `cloud ${entry.parent_id} should not draw`).toBeUndefined()
            continue
          }
          expect(drawn, `cloud ${entry.parent_id}`).toBeDefined()
          expect(drawn!.ids).toEqual(entry.ids)
        }
      })

      it('places every point where the desktop engine does', () => {
        const { out } = batchesOf(parse(), showHidden)
        let checked = 0
        for (const entry of reference[key]) {
          const drawn = out.get(entry.parent_id)
          if (!drawn) continue
          for (let i = 0; i < entry.ids.length; i++) {
            const [x, y, z] = entry.positions[i]
            const label = `node ${entry.ids[i]} (cloud ${entry.parent_id})`
            expect(drawn.positions[i * 3], `${label} x`).toBeCloseTo(x, 5)
            expect(drawn.positions[i * 3 + 1], `${label} y`).toBeCloseTo(y, 5)
            expect(drawn.positions[i * 3 + 2], `${label} z`).toBeCloseTo(z, 5)
            checked++
          }
        }
        // A silent zero here would make the whole file vacuous.
        expect(checked).toBeGreaterThan(15)
      })

      it('colours every point from its own row', () => {
        const { out } = batchesOf(parse(), showHidden)
        for (const entry of reference[key]) {
          const drawn = out.get(entry.parent_id)
          if (!drawn) continue
          for (let i = 0; i < entry.ids.length; i++) {
            const [r, g, b, a] = entry.colors[i]
            const label = `node ${entry.ids[i]}`
            // The desktop keeps bytes; this app keeps the 0–1 the GPU wants,
            // raw (no sRGB decode) to match its LinearSRGB output — so the two
            // agree at byte precision after the scale.
            expect(drawn.colors[i * 4] * 255, `${label} r`).toBeCloseTo(r, 3)
            expect(drawn.colors[i * 4 + 1] * 255, `${label} g`).toBeCloseTo(g, 3)
            expect(drawn.colors[i * 4 + 2] * 255, `${label} b`).toBeCloseTo(b, 3)
            expect(drawn.colors[i * 4 + 3] * 255, `${label} a`).toBeCloseTo(a, 3)
          }
        }
      })
    })
  }

  it('agrees with the desktop on a rotated, scaled ancestor chain', () => {
    // Cloud 12 hangs off a node translated (40, 10, 5), rotated on all three
    // axes and scaled (2, 2, 3). Called out separately because it is the case a
    // hand-rolled "just add the parent position" overlay would pass every other
    // test and fail here.
    const { out } = batchesOf(parse(), false)
    const entry = reference.clouds.find((c) => c.parent_id === 12)!
    const drawn = out.get(12)!
    const first = new THREE.Vector3(drawn.positions[0], drawn.positions[1], drawn.positions[2])
    expect(first.distanceTo(new THREE.Vector3(...entry.positions[0]))).toBeLessThan(TOLERANCE)
    // …and it is genuinely somewhere else, so the check has teeth.
    expect(first.length()).toBeGreaterThan(30)
  })

  it('agrees on a topo_scale parent and on a World Grid parent', () => {
    const { out } = batchesOf(parse(), false)
    for (const parentId of [18, 27]) {
      const entry = reference.clouds.find((c) => c.parent_id === parentId)!
      const drawn = out.get(parentId)!
      for (let i = 0; i < entry.ids.length; i++) {
        const p = new THREE.Vector3(
          drawn.positions[i * 3],
          drawn.positions[i * 3 + 1],
          drawn.positions[i * 3 + 2],
        )
        expect(p.distanceTo(new THREE.Vector3(...entry.positions[i]))).toBeLessThan(TOLERANCE)
      }
    }
  })
})
